        return f'{best[1]}+0x{offset:x}'
    return '???'

for thread, addresses in addrs.items():
    print(f'\n{thread}:')
    for a in addresses:
        sym = find_symbol(a)
        print(f'  0x{a:08x} -> {sym}')
