from elftools.elf.elffile import ELFFile
from elftools.elf.sections import SymbolTableSection

# Load the debug ELF
with open('libmonosgen-2.0.so.dbg', 'rb') as f:
    elf = ELFFile(f)

    # Collect all FUNC symbols
    syms = []
    for section in elf.iter_sections():
        if isinstance(section, SymbolTableSection):
            for sym in section.iter_symbols():
                if sym['st_info']['type'] == 'STT_FUNC' and sym['st_value'] != 0:
                    syms.append((sym['st_value'], sym['st_size'], sym.name))

    syms.sort()
    print(f'Loaded {len(syms)} function symbols')

    def find_symbol(target):
        best = None
        for addr, size, name in syms:
            if addr <= target:
                best = (addr, size, name)
            elif addr > target:
                break
        if best:
            offset = target - best[0]
            return f'{best[2]}+0x{offset:x}'
        return '???'

    # All libmonosgen-2.0.so frames across all threads
    frames = {
        'Thread 7020 (main - uiTest.MauiTest)': [
            (1, 0x222098),
            (2, 0x2241ac),
            (3, 0x1abc80),
            (4, 0x16de04),
        ],
        'Thread 7046 (SGen worker)': [
            (2, 0x2f4b20),
            (3, 0x2f4c84),
        ],
        'Thread 7048 (Finalizer)': [
            (2, 0x2c1a40),
        ],
    }

    for thread, addrs in frames.items():
        print(f'\n{thread}:')
        for frame_num, addr in addrs:
            sym = find_symbol(addr)
            print(f'  #{frame_num:02d} pc 0x{addr:08x}  {sym}')
"

