from elftools.elf.elffile import ELFFile
from elftools.dwarf.descriptions import describe_form_class

with open('libmonosgen-2.0.so.dbg', 'rb') as f:
    elf = ELFFile(f)
    if not elf.has_dwarf_info():
        print('No DWARF info')
        exit(1)

    dwarfinfo = elf.get_dwarf_info()

    # Collect all subprograms with their address ranges
    funcs = []
    for CU in dwarfinfo.iter_CUs():
        for DIE in CU.iter_DIEs():
            if DIE.tag == 'DW_TAG_subprogram':
                if 'DW_AT_low_pc' in DIE.attributes and 'DW_AT_high_pc' in DIE.attributes:
                    low = DIE.attributes['DW_AT_low_pc'].value
                    high_attr = DIE.attributes['DW_AT_high_pc']
                    # high_pc can be absolute or offset
                    form_class = describe_form_class(high_attr.form)
                    if form_class == 'constant':
                        high = low + high_attr.value
                    else:
                        high = high_attr.value
                    name = DIE.attributes.get('DW_AT_name')
                    if name:
                        funcs.append((low, high, name.value.decode('utf-8')))

    funcs.sort()
    print(f'Found {len(funcs)} DWARF subprograms')

    def find_func(target):
        for low, high, name in funcs:
            if low <= target < high:
                return f'{name}+0x{target-low:x}'
        return None

    all_addrs = [0x222098, 0x2241ac, 0x1abc80, 0x16de04, 0x2f4b20, 0x2f4c84, 0x2c1a40]
    for a in all_addrs:
        result = find_func(a)
        print(f'  0x{a:08x} -> {result}')
" 2>&1

