from elftools.elf.elffile import ELFFile
from elftools.elf.sections import SymbolTableSection

with open('libmonosgen-2.0.so.dbg', 'rb') as f:
    elf = ELFFile(f)
    syms = []
    for section in elf.iter_sections():
        if isinstance(section, SymbolTableSection):
            for sym in section.iter_symbols():
                if sym['st_value'] != 0 and sym.name and not sym.name.startswith('__Cortex'):
                    syms.append((sym['st_value'], sym['st_size'], sym.name, sym['st_info']['type']))
    syms.sort()

    # Find what's around 0x2f4b20
    for target in [0x2f4b20, 0x2f4c84]:
        print(f'\nNear 0x{target:08x}:')
        prev = None
        for i, (addr, size, name, stype) in enumerate(syms):
            if addr > target:
                if prev:
                    pa, ps, pn, pt = prev
                    print(f'  BEFORE: 0x{pa:08x} size=0x{ps:x} {pn} ({pt}) ends at 0x{pa+ps:08x}')
                print(f'  AFTER:  0x{addr:08x} size=0x{size:x} {name} ({stype})')
                break
            prev = (addr, size, name, stype)
"

