from elftools.elf.elffile import ELFFile
from elftools.elf.sections import SymbolTableSection

# These addresses are in .data.rel.ro - they're data, not code
# Check what data symbols are at those locations
with open('libmonosgen-2.0.so.dbg', 'rb') as f:
    elf = ELFFile(f)
    syms = []
    for section in elf.iter_sections():
        if isinstance(section, SymbolTableSection):
            for sym in section.iter_symbols():
                if sym['st_value'] != 0 and sym['st_info']['type'] in ('STT_OBJECT', 'STT_NOTYPE') and sym.name:
                    syms.append((sym['st_value'], sym['st_size'], sym.name, sym['st_info']['type']))
    syms.sort()

    for target in [0x2f4b20, 0x2f4c84]:
        print(f'Data symbols near 0x{target:08x}:')
        for addr, size, name, stype in syms:
            if addr <= target < addr + max(size, 1):
                print(f'  MATCH: 0x{addr:08x} size=0x{size:x} {name} ({stype}) offset=+0x{target-addr:x}')
            elif abs(addr - target) < 0x100:
                print(f'  NEAR:  0x{addr:08x} size=0x{size:x} {name} ({stype})')
        print()
"

